import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = 1;
        while (T-- > 0) {
            String s = scanner.next();
            if (s.length() == 1) {
                if (s.charAt(0) == '0' || s.charAt(0) == '_' || s.charAt(0) == 'X') {
                    System.out.println(1);
                } else {
                    System.out.println(0);
                }
            } else {
                boolean containsX = false;
                for (int i = 0; i < s.length(); i++) {
                    if (s.charAt(i) == 'X') {
                        containsX = true;
                        break;
                    }
                }
                if (!containsX) {
                    System.out.println(calculate(s));
                } else {
                    int totalSum = 0;
                    for (int digit = 0; digit <= 9; digit++) {
                        char[] chArr = s.toCharArray();
                        for (int j = 0; j < s.length(); j++) {
                            if (chArr[j] == 'X') {
                                chArr[j] = (char) (digit + '0');
                            }
                        }
                        String newStr = String.valueOf(chArr);
                        totalSum += calculate(newStr);
                    }
                    System.out.println(totalSum);
                }
            }
        }
        scanner.close();
    }

    public static int calculate(String s) {
        int length = s.length();
        int p = 0;
        if (s.charAt(0) != '0') p = 1;
        for (int i = 0; i < length - 2; i++) {
            if (s.charAt(i) == '_') {
                p *= (i == 0) ? 9 : 10;
            }
        }
        int p1 = 0;
        if (s.charAt(length - 1) == '_' && s.charAt(length - 2) == '_') {
            p1 = (length == 2) ? 3 : 4;
        } else if (s.charAt(length - 1) == '_') {
            if (s.charAt(length - 2) == '0' || s.charAt(length - 2) == '5' || s.charAt(length - 2) == '2' || s.charAt(length - 2) == '7') {
                p1 = 1;
            }
        } else if (s.charAt(length - 2) == '_') {
            if (s.charAt(length - 1) == '0') {
                p1 = (length == 2) ? 1 : 2;
            } else if (s.charAt(length - 1) == '5') {
                p1 = 2;
            }
        } else {
            int val = Integer.parseInt(s.substring(length - 2));
            if (val % 25 == 0) p1 = 1;
        }
        return p * p1;
    }
}
